style.css:
/* Fundo escuro */
body {
    background-color: #0d0d0d !important;
    color: #f5f5f5 !important;
    font-family: 'Segoe UI', sans-serif;
}

/* Estilo dos links */
a {
    color: #b3b3ff !important;
}

/* Títulos escuros */
h1, h2, h3, h4, h5, h6 {
    color: #ffffff !important;
}

/* Caixas e seções transparentes */
div, section, header, footer, nav, main, article, aside {
    background-color: transparent !important;
    box-shadow: none !important;
    border: none !important;
}

/* Input escuro */
input[type="text"], input[type="search"] {
    background-color: #1a1a1a !important;
    color: #ffffff !important;
    border: 1px solid #444 !important;
}

/* Imagem de fundo com transparência */
body::before {
    content: "";
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: url('https://i.imgur.com/EJqRAZk.jpeg') no-repeat center center fixed;
    background-size: contain;
    opacity: 0.05;
    z-index: -1;
}
